package ultra.downloads;
import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=28)
public class ResolverFallbackTest {
 Hooks.Probe oldProbe;@After public void restoreProbe(){Hooks.probe=oldProbe;}
 @Before public void context(){oldProbe=Hooks.probe;Hooks.probe=new Hooks.Probe(){public void check(Hooks.Audio a){}};app.revanced.extension.shared.utils.Utils.testContext=Robolectric.buildActivity(android.app.Activity.class).setup().get();}
 @Test public void realNonceOverloadNoNull()throws Exception{String[] n=Hooks.nonces();assertEquals(12,n[0].length());assertEquals(16,n[1].length());try{Class.forName("com.liskovsoft.googlecommon.common.helpers.YouTubeHelper").getMethod("generateContentPlaybackNonce",String.class).invoke(null,new Object[]{null});fail();}catch(InvocationTargetException e){assertTrue(ResolveErrors.root(e) instanceof NullPointerException);}}
 @Test public void failedNativeRouteFallsThroughAndShowsCause(){List<String> errors=new ArrayList<>();Hooks.Audio a=Hooks.attempt("native",new Hooks.Route(){public Hooks.Audio get()throws Exception{throw new InvocationTargetException(new NullPointerException("nonce length failed"));}},errors);assertNull(a);assertTrue(errors.get(0).contains("NullPointerException: nonce length failed"));final Hooks.Audio expected=new Hooks.Audio();assertSame(expected,Hooks.attempt("fallback",new Hooks.Route(){public Hooks.Audio get(){return expected;}},errors));assertEquals(1,errors.size());}
 @Test public void diagnosticMessageRedactsLinksAndTokens(){String s=ResolveErrors.describe(new InvocationTargetException(new java.io.IOException("request https://youtube.invalid/?token=SECRET Authorization=PRIVATE Bearer PRIVATE")));assertFalse(s.contains("SECRET"));assertFalse(s.contains("PRIVATE"));assertFalse(s.contains("youtube.invalid"));assertTrue(s.startsWith("IOException:"));}
 @Test public void independentFallbackCanReturnEvenWhenHostClientTableFails()throws Exception{PlayerFallback.Http old=PlayerFallback.http;final int[] calls={0};PlayerFallback.http=new PlayerFallback.Http(){public JSONObject post(JSONObject body,Map<String,String> headers)throws Exception{calls[0]++;assertEquals("abcdefghijk",body.getString("videoId"));assertTrue(headers.containsKey("User-Agent"));return response();}};try{Hooks.Audio a=PlayerFallback.resolve("abcdefghijk",null,"best",new ArrayList<String>());assertNotNull(a);assertEquals(180000,a.bitrate);assertTrue(calls[0]>0);}finally{PlayerFallback.http=old;}}
 @Test public void deniedCandidateDoesNotShortCircuitOtherRoutes(){final Hooks.Audio a=new Hooks.Audio(),b=new Hooks.Audio();a.url="denied";b.url="accepted";Hooks.probe=new Hooks.Probe(){public void check(Hooks.Audio x)throws Exception{if(x==a)throw new java.io.IOException("Audio server returned HTTP 403");}};List<String> errors=new ArrayList<>();assertNull(Hooks.attempt("cached",()->a,errors));assertSame(b,Hooks.attempt("fresh",()->b,errors));assertEquals(1,errors.size());assertTrue(errors.get(0).contains("403"));}
 JSONObject response()throws Exception{return new JSONObject("{\"playabilityStatus\":{\"status\":\"OK\"},\"videoDetails\":{\"videoId\":\"abcdefghijk\"},\"streamingData\":{\"adaptiveFormats\":[{\"itag\":140,\"lastModified\":123,\"bitrate\":128000,\"contentLength\":45678,\"mimeType\":\"audio/mp4\",\"url\":\"https://rr1.googlevideo.com/videoplayback?expire=4102444800\"},{\"itag\":251,\"lastModified\":456,\"bitrate\":180000,\"contentLength\":99999,\"mimeType\":\"audio/webm\",\"url\":\"https://rr1.googlevideo.com/videoplayback?expire=4102444800\"}]}}");}
 @Test public void fallbackBestAndRenditionIdentity()throws Exception{Hooks.Audio a=PlayerFallback.select(response(),"abcdefghijk",null,"best","ua");assertEquals(180000,a.bitrate);assertEquals("251:456",a.key);assertEquals(99999,a.size);assertEquals("ua",a.agent);assertEquals(128000,PlayerFallback.select(response(),"abcdefghijk","140:123","best","ua").bitrate);assertNull(PlayerFallback.select(response(),"abcdefghijk","140:999","best","ua"));}
 @Test public void wrongVideoProtectedCipherAndForeignUrlsRejected()throws Exception{JSONObject j=response();try{PlayerFallback.select(j,"bcdefghijkl",null,"best","");fail();}catch(java.io.IOException expected){}JSONArray a=j.getJSONObject("streamingData").getJSONArray("adaptiveFormats");a.getJSONObject(0).put("drmFamilies",new JSONArray().put("x"));a.getJSONObject(1).put("url","https://attacker.invalid/audio");assertNull(PlayerFallback.select(j,"abcdefghijk",null,"best",""));a.getJSONObject(1).remove("url");a.getJSONObject(1).put("signatureCipher","not interpreted");assertNull(PlayerFallback.select(j,"abcdefghijk",null,"best",""));}
 public static class FakeClient{public String getClientName(){return "ANDROID";}public String getClientVersion(){return "8.30.54";}public String getDeviceMake(){return "";}public String getDeviceModel(){return "";}public String getOsName(){return "Android";}public String getOsVersion(){return "15";}public String getAndroidSdkVersion(){return "35";}public String getUserAgent(){return "test-agent";}public int getId(){return 3;}}
 @Test public void guestHeadersNeverContainAuthorization()throws Exception{Object client=new FakeClient();Map<String,String> account=new HashMap<>();account.put("Authorization","test-only");account.put("X-Goog-Visitor-Id","test-only-visitor");assertFalse(PlayerFallback.headers(client,account,false).containsKey("Authorization"));assertEquals("test-only",PlayerFallback.headers(client,account,true).get("Authorization"));JSONObject b=PlayerFallback.body(client,"abcdefghijk",account);assertEquals("abcdefghijk",b.getString("videoId"));assertFalse(b.toString().contains("Authorization"));}
}
